def get_schema():
    global user_graphql_endpoint
    query = '
    query IntrospectionQuery {
        __schema {
            types {
                name
                kind
                fields {
                    name
                    type {
                        name
                        kind
                        ofType {
                            name
                            kind
                        }
                    }
                }
            }
        }
    }'
    request = requests.post(user_graphql_endpoint, json={'query': query})
    json_output = request.json()
    simplified_schema = {}
    for type_info in json_output['data']['__schema']['types']:
        if not type_info['name'].startswith('__'):
            fields = type_info.get('fields')
            if fields is not None and fields is not []:
                simplified_schema[type_info['name']] = {'kind': type_info['kind'], 'fields': ', '.join([field['name'] for field in fields if not field['name'].startswith('__')])}
            else:
                simplified_schema[type_info['name']] = {'kind': type_info['kind']}
    return simplified_schema

