is_retriable = lambda e: isinstance(e, genai.errors.APIError) and e.code in {429, 503}
genai.models.Models.generate_content = retry.Retry(predicate=is_retriable)(genai.models.Models.generate_content)
client = genai.Client(api_key=GOOGLE_API_KEY)

class GeminiEmbeddingFunction(EmbeddingFunction):
    document_mode = True

    @retry.Retry(predicate=is_retriable)
    def __call__(self, input: Documents) -> Embeddings:
        if self.document_mode:
            embedding_task = 'retrieval_document'
        else:
            embedding_task = 'retrieval_query'
        response = client.models.embed_content(model='models/text-embedding-004', contents=input, config=types.EmbedContentConfig(task_type=embedding_task))
        return [e.values for e in response.embeddings]
embed_fn = GeminiEmbeddingFunction()
embed_fn.document_mode = True
chroma_client = chromadb.PersistentClient(path=DB_PATH)
db = chroma_client.get_or_create_collection(name=DB_NAME, embedding_function=GeminiEmbeddingFunction(client, document_mode=True))

@tool
def search_cantera_docs(query: str, n_results: int=10) -> str:
    if db is None or embed_fn is None:
        return 'Error: database or embedding function has not been initialised.'
    if db.count() == 0:
        return 'Error: document database is empty.'
    original_mode = getattr(embed_fn, 'document_mode', True)
    embed_fn.document_mode = False
    try:
        res = db.query(query_texts=[query], n_results=n_results)
    except Exception as exc:
        return f'Error during documentation search: {exc}'
    finally:
        embed_fn.document_mode = original_mode
    chunks: List[str] = res.get('documents', [[]])[0]
    if not chunks:
        return 'No relevant documentation found.'
    return '\n'.join((f"- {c.replace(chr(10), ' ')}" for c in chunks))

