import os
from pathlib import Path
from langchain_chroma import Chroma
from langchain_core.runnables import RunnableConfig
from langchain_core.tools import tool
DATA_DIR = Path(__file__).resolve().parent / 'data'
VECTOR_DIR = DATA_DIR / 'chroma'
COLLECTION_NAME = 'uploaded_documents'

def _get_embeddings():
    provider = os.getenv('RAG_EMBEDDING_PROVIDER', '').strip().lower()
    if not provider:
        provider = 'google' if os.getenv('GOOGLE_API_KEY') else 'ollama'
    if provider == 'google':
        api_key = os.getenv('GOOGLE_API_KEY')
        if not api_key:
            raise RuntimeError("RAG_EMBEDDING_PROVIDER is 'google' but GOOGLE_API_KEY is not configured.")
        from langchain_google_genai import GoogleGenerativeAIEmbeddings
        return GoogleGenerativeAIEmbeddings(model=os.getenv('RAG_GOOGLE_EMBEDDING_MODEL', 'models/gemini-embedding-001'), google_api_key=api_key)
    if provider == 'ollama':
        from langchain_ollama import OllamaEmbeddings
        model = os.getenv('RAG_OLLAMA_EMBEDDING_MODEL', 'nomic-embed-text')
        return OllamaEmbeddings(model=model)
    raise ValueError("Unsupported RAG_EMBEDDING_PROVIDER. Choose 'google' or 'ollama'.")

def _vector_store() -> Chroma:
    DATA_DIR.mkdir(parents=True, exist_ok=True)
    return Chroma(collection_name=COLLECTION_NAME, persist_directory=str(VECTOR_DIR), embedding_function=_get_embeddings())

@tool
def search_uploaded_document(query: str, config: RunnableConfig) -> str:
    thread_id = (config.get('configurable') or {}).get('thread_id')
    if not isinstance(thread_id, str) or not thread_id:
        return 'Document search failed: conversation context is unavailable.'
    query = query.strip()
    if not query:
        return 'Document search failed: enter a question to search for.'
    results = _vector_store().similarity_search(query, k=4, filter={'thread_id': thread_id})
    if not results:
        return 'No matching content was found in documents uploaded to this conversation.'
    return '\n\n'.join((f"Source: {document.metadata.get('source', 'uploaded document')}\n{document.page_content}" for document in results))

from langchain_core.tools import tool

@tool
def web_search(query: str) -> str:
    import requests
    from bs4 import BeautifulSoup
    from urllib.parse import quote_plus, unquote
    headers = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'}
    try:
        url = f'https://html.duckduckgo.com/html/?q={quote_plus(query)}'
        resp = requests.get(url, headers=headers, timeout=10)
        soup = BeautifulSoup(resp.text, 'html.parser')
        results = []
        for item in soup.select('div.result, div.web-result'):
            a = item.select_one('a.result__a')
            snippet_el = item.select_one('a.result__snippet')
            if not a:
                continue
            title = a.get_text(strip=True)
            raw_href = a.get('href', '')
            if 'uddg=' in raw_href:
                from urllib.parse import parse_qs, urlparse
                parsed = urlparse(raw_href)
                qs = parse_qs(parsed.query)
                link = qs.get('uddg', [raw_href])[0]
            else:
                link = raw_href
            snippet = snippet_el.get_text(strip=True) if snippet_el else ''
            if title and link:
                results.append(f'[{len(results) + 1}] {title}\n{snippet}\nURL: {link}')
            if len(results) >= 5:
                break
        if results:
            return '\n\n---\n\n'.join(results)
    except Exception:
        pass
    try:
        from duckduckgo_search import DDGS
        with DDGS() as ddgs:
            hits = list(ddgs.text(query, max_results=5))
        if hits:
            formatted = []
            for i, r in enumerate(hits, 1):
                formatted.append(f"[{i}] {r['title']}\n{r['body']}\nURL: {r['href']}")
            return '\n\n---\n\n'.join(formatted)
    except Exception:
        pass
    return 'No search results found.'

from langchain_core.tools import tool

@tool
def browse_webpage(url: str) -> str:
    try:
        import requests
        from bs4 import BeautifulSoup
        resp = requests.get(url, timeout=10, headers={'User-Agent': 'Mozilla/5.0'})
        soup = BeautifulSoup(resp.text, 'html.parser')
        for tag in soup(['script', 'style', 'nav', 'footer', 'header']):
            tag.decompose()
        text = soup.get_text(separator='\n', strip=True)
        return text[:3000] if len(text) > 3000 else text
    except Exception as e:
        return f'Failed to fetch webpage: {e}'

