import json
import re
PRIORITY_WORDS = {'urgent': 4, 'asap': 4, 'today': 3, 'tomorrow': 3, 'cannot': 2, 'can’t': 2, 'cancel': 2, 'need': 2, 'help': 1}
UNAVAILABILITY_PATTERN = re.compile("can't|cannot|unavailable|cancel(?:led|ed)?|broken|breakdown|car trouble|can't make it", re.I)

def _score(message: str) -> int:
    lowered = message.lower()
    return sum((weight for word, weight in PRIORITY_WORDS.items() if word in lowered))

def _name(message: str, index: int) -> str:
    match = re.search('(?:^|[,.\\-—]\\s*)([A-Z][a-z]{1,20})(?:\\s+[A-Z][a-z]{1,20})?', message)
    return match.group(1) if match else f'Volunteer {index + 1}'

@tool
def extract_volunteer_signals(messages_json: str) -> str:
    messages = json.loads(messages_json)
    signals = []
    for index, message in enumerate(messages):
        signals.append({'label': _name(message, index), 'priority': _score(message), 'mentions_unavailability': bool(UNAVAILABILITY_PATTERN.search(message)), 'summary': message[:220]})
    return json.dumps(signals)

import json

@tool
def build_action_queue(signals_json: str, goal: str) -> str:
    signals = json.loads(signals_json)
    ranked = sorted(signals, key=lambda signal: signal['priority'], reverse=True)
    queue = []
    for signal in ranked[:5]:
        action = 'Confirm availability' if signal['mentions_unavailability'] else 'Acknowledge update'
        queue.append({'owner': 'Coordinator', 'action': f"{action} with {signal['label']} for {goal}", 'why': signal['summary'], 'approval_required': True})
    return json.dumps(queue)

