from langchain.tools import tool

@tool
def recommend_clothing(weather_description: str, temperature: float) -> str:
    cold = temperature < 10
    cool = 10 <= temperature < 18
    mild = 18 <= temperature < 24
    warm = 24 <= temperature < 30
    hot = temperature >= 30
    rainy = any((x in weather_description.lower() for x in ['rain', 'drizzle', 'shower']))
    snowy = any((x in weather_description.lower() for x in ['snow', 'sleet', 'hail']))
    windy = 'wind' in weather_description.lower()
    sunny = any((x in weather_description.lower() for x in ['sun', 'clear', 'sunny']))
    recommendations = []
    if cold:
        recommendations.extend(['Kalın mont veya şişme mont', 'Termal içlik', 'Kazak veya polar', 'Bere', 'Eldiven', 'Atkı', 'Kalın çoraplar', 'Bot'])
    elif cool:
        recommendations.extend(['Hafif mont veya ceket', 'Kazak veya hafif polar', 'Uzun kollu gömlek', 'Kot pantolon veya kumaş pantolon', 'Hafif atkı (isteğe bağlı)', 'Kapalı ayakkabı'])
    elif mild:
        recommendations.extend(['Hafif hırka veya kazak', 'Uzun veya kısa kollu gömlek', 'Pantolon veya kot', 'Spor ayakkabı veya günlük ayakkabı'])
    elif warm:
        recommendations.extend(['Tişört veya kısa kollu gömlek', 'Hafif pantolon veya şort', 'Elbise veya etek', 'Sandalet veya spor ayakkabı', 'Güneş koruması için hafif şapka'])
    elif hot:
        recommendations.extend(['Hafif tişört veya atlet', 'Şort veya hafif etek', 'Sandalet', 'Güneş gözlüğü', 'Güneş şapkası', 'Pamuk veya keten gibi nefes alabilen kumaşları tercih edin'])
    if rainy:
        recommendations.extend(['Yağmurluk veya su geçirmez ceket', 'Şemsiye', 'Su geçirmez ayakkabı veya botlar'])
    if snowy:
        recommendations.extend(['İyi tutunma sağlayan su geçirmez botlar', 'Su geçirmez mont ve pantolon', 'Yalıtımlı eldivenler'])
