@mcp.tool()
async def explain_query_plan(sql: str, ctx: Context) -> str:
    db_context: DatabaseContext = ctx.request_context.lifespan_context
    try:
        plan = await db_context.explain_query_plan(sql)
        if plan.get('error'):
            return wrap_untrusted(f"Explain plan unavailable: {plan['error']}")
        if not plan.get('execution_plan'):
            return wrap_untrusted('No execution plan rows returned.')
        lines = ['Execution Plan:'] + [f'  {step}' for step in plan['execution_plan']]
        if plan.get('optimization_suggestions'):
            lines.append('\nSuggestions:')
            for s in plan['optimization_suggestions']:
                lines.append(f'  - {s}')
        return wrap_untrusted('\n'.join(lines))
    except PermissionError as e:
        return wrap_untrusted(f'Permission error: {e}')
    except oracledb.Error as e:
        return wrap_untrusted(f'Database error obtaining plan: {e}')
    except Exception as e:
        return wrap_untrusted(f'Unexpected error obtaining plan: {e}')

from typing import Any, Dict, List, Optional, AsyncIterator, Callable, TypeVar, Awaitable, Union
import os
import httpx
from contextlib import asynccontextmanager
from dataclasses import dataclass
from functools import wraps
from fastapi import FastAPI, HTTPException
from mcp.server.fastmcp import FastMCP, Context
import logging
logger = logging.getLogger(__name__)
SUPERSET_BASE_URL = os.getenv('SUPERSET_BASE_URL', 'http://localhost:8088')
ACCESS_TOKEN_STORE_PATH = os.path.join(os.path.dirname(__file__), '.superset_token')
app = FastAPI(title='Superset MCP Server')

@dataclass
class SupersetContext:
    client: httpx.AsyncClient
    base_url: str
    access_token: Optional[str] = None
    csrf_token: Optional[str] = None
    app: FastAPI = None

def load_stored_token() -> Optional[str]:
    try:
        if os.path.exists(ACCESS_TOKEN_STORE_PATH):
            with open(ACCESS_TOKEN_STORE_PATH, 'r') as f:
                return f.read().strip()
    except Exception:
        return None
    return None

@asynccontextmanager
async def superset_lifespan(server: FastMCP) -> AsyncIterator[SupersetContext]:
    logger.info('Initializing Superset context...')
    client = httpx.AsyncClient(base_url=SUPERSET_BASE_URL, timeout=30.0)
    ctx = SupersetContext(client=client, base_url=SUPERSET_BASE_URL, app=app)
    stored_token = load_stored_token()
    if stored_token:
        ctx.access_token = stored_token
        client.headers.update({'Authorization': f'Bearer {stored_token}'})
        logger.info('Using stored access token')
        try:
            response = await client.get('/api/v1/me/')
            if response.status_code != 200:
                logger.info(f'Stored token is invalid (status {response.status_code}). Will need to re-authenticate.')
                ctx.access_token = None
                client.headers.pop('Authorization', None)
        except Exception as e:
            logger.info(f'Error verifying stored token: {e}')
            ctx.access_token = None
            client.headers.pop('Authorization', None)
    try:
        yield ctx
    finally:
        logger.info('Shutting down Superset context...')
        await client.aclose()
mcp = FastMCP('superset', lifespan=superset_lifespan, dependencies=['fastapi', 'uvicorn', 'python-dotenv', 'httpx'])

def handle_api_errors(func: Callable[..., Awaitable[Dict[str, Any]]]) -> Callable[..., Awaitable[Dict[str, Any]]]:

    @wraps(func)
    async def wrapper(ctx: Context, *args, **kwargs) -> Dict[str, Any]:
        try:
            return await func(ctx, *args, **kwargs)
        except Exception as e:
            function_name = func.__name__
            return {'error': f'Error in {function_name}: {str(e)}'}
    return wrapper

@mcp.tool()
@handle_api_errors
async def superset_config_get_base_url(ctx: Context) -> Dict[str, Any]:
    superset_ctx: SupersetContext = ctx.request_context.lifespan_context
    return {'base_url': superset_ctx.base_url, 'message': f'Connected to Superset instance at: {superset_ctx.base_url}'}

import logging
from enum import Enum
from typing import List, Dict, Optional, Union, Any
