mcp = FastMCP('telegram')
logger = logging.getLogger('telegram_mcp')

class ErrorCategory(str, Enum):
    CHAT = 'CHAT'
    MSG = 'MSG'
    CONTACT = 'CONTACT'
    GROUP = 'GROUP'
    MEDIA = 'MEDIA'
    PROFILE = 'PROFILE'
    AUTH = 'AUTH'
    ADMIN = 'ADMIN'

def log_and_format_error(function_name: str, error: Exception, prefix: Optional[Union[ErrorCategory, str]]=None, user_message: str=None, **kwargs) -> str:
    if isinstance(prefix, str) and prefix == 'VALIDATION-001':
        error_code = prefix
    else:
        if prefix is None:
            for category in ErrorCategory:
                if category.name.lower() in function_name.lower():
                    prefix = category
                    break
        prefix_str = prefix.value if isinstance(prefix, ErrorCategory) else prefix or 'GEN'
        error_code = f'{prefix_str}-ERR-{abs(hash(function_name)) % 1000:03d}'
    context = ', '.join((f'{k}={v}' for k, v in kwargs.items()))
    logger.error(f'Error in {function_name} ({context}) - Code: {error_code}', exc_info=True)
    if user_message:
        return user_message
    return f'An error occurred (code: {error_code}). Check mcp_errors.log for details.'

@mcp.tool(annotations=ToolAnnotations(title='Get Chats', openWorldHint=True, readOnlyHint=True))
async def get_chats(page: int=1, page_size: int=20) -> str:
    try:
        dialogs = await client.get_dialogs()
        start = (page - 1) * page_size
        end = start + page_size
        if start >= len(dialogs):
            return 'Page out of range.'
        chats = dialogs[start:end]
        lines = []
        for dialog in chats:
            entity = dialog.entity
            chat_id = entity.id
            title = getattr(entity, 'title', None) or getattr(entity, 'first_name', 'Unknown')
            lines.append(f'Chat ID: {chat_id}, Title: {title}')
        return '\n'.join(lines)
    except Exception as e:
        return log_and_format_error('get_chats', e)

