@mcp.tool(annotations=ToolAnnotations(title='Add Contact', openWorldHint=True, destructiveHint=True, idempotentHint=True))
async def add_contact(phone: str, first_name: str, last_name: str='') -> str:
    try:
        from telethon.tl.types import InputPhoneContact
        result = await client(functions.contacts.ImportContactsRequest(contacts=[InputPhoneContact(client_id=0, phone=phone, first_name=first_name, last_name=last_name)]))
