        error_code = f'{prefix_str}-ERR-{abs(hash(function_name)) % 1000:03d}'
    context = ', '.join((f'{k}={v}' for k, v in kwargs.items()))
    logger.error(f'Error in {function_name} ({context}) - Code: {error_code}', exc_info=True)
    if user_message:
        return user_message
    return f'An error occurred (code: {error_code}). Check mcp_errors.log for details.'

@mcp.tool(annotations=ToolAnnotations(title='Get Drafts', openWorldHint=True, readOnlyHint=True))
async def get_drafts() -> str:
    try:
        result = await client(functions.messages.GetAllDraftsRequest())
        drafts_info = []
        if hasattr(result, 'updates'):
            for update in result.updates:
                if hasattr(update, 'draft') and update.draft:
                    draft = update.draft
                    peer_id = None
                    if hasattr(update, 'peer'):
                        peer = update.peer
                        if hasattr(peer, 'user_id'):
                            peer_id = peer.user_id
                        elif hasattr(peer, 'chat_id'):
                            peer_id = -peer.chat_id
                        elif hasattr(peer, 'channel_id'):
                            peer_id = -1000000000000 - peer.channel_id
                    draft_data = {'peer_id': peer_id, 'message': getattr(draft, 'message', ''), 'date': draft.date.isoformat() if hasattr(draft, 'date') and draft.date else None, 'no_webpage': getattr(draft, 'no_webpage', False), 'reply_to_msg_id': draft.reply_to.reply_to_msg_id if hasattr(draft, 'reply_to') and draft.reply_to else None}
                    drafts_info.append(draft_data)
        if not drafts_info:
            return 'No drafts found.'
        return json.dumps({'drafts': drafts_info, 'count': len(drafts_info)}, indent=2, default=json_serializer)
