import requests
from mcp.server.fastmcp import FastMCP
from datetime import datetime, timedelta, UTC
import os
mcp = FastMCP('CryptoSentiment')
SANTIMENT_API_KEY = os.getenv('SANTIMENT_API_KEY')
SANTIMENT_API_URL = 'https://api.santiment.net/graphql'
HEADERS = {'Authorization': f'Apikey {SANTIMENT_API_KEY}'}

def fetch_trending_words(days: int=7) -> dict:
    now = datetime.now(UTC)
    to_date = now
    from_date = to_date - timedelta(days=days)
    query = f'\n    {{\n      getTrendingWords(size: 10, from: "{from_date.isoformat()}", to: "{to_date.isoformat()}", interval: "1d") {{\n        datetime\n        topWords {{\n          word\n          score\n        }}\n      }}\n    }}\n    '
    response = requests.post(SANTIMENT_API_URL, json={'query': query}, headers=HEADERS)
    result = response.json()
    if result.get('errors'):
        raise Exception(f"API error: {result.get('errors')}")
    return result

@mcp.tool()
def get_trending_words(days: int=7, top_n: int=5) -> str:
    try:
        data = fetch_trending_words(days)
        trends = data.get('data', {}).get('getTrendingWords', [])
        if not trends:
            return 'Unable to fetch trending words. Check API subscription limits or connectivity.'
        word_scores = {}
        for day in trends:
            for word_data in day['topWords']:
                word = word_data['word']
                score = word_data['score']
                if word in word_scores:
                    word_scores[word] += score
                else:
                    word_scores[word] = score
        if not word_scores:
            return 'No trending words data available for the specified period.'
        top_words = sorted(word_scores.items(), key=lambda x: x[1], reverse=True)[:top_n]
        top_words_list = [word for word, _ in top_words]
        return f"Top {top_n} trending words over the past {days} days: {', '.join(top_words_list)}."
    except Exception as e:
        return f'Error fetching trending words: {str(e)}'

import requests
from mcp.server.fastmcp import FastMCP
import os
API_KEY = os.getenv('CRYPTOPANIC_API_KEY')
API_PLAN = os.getenv('CRYPTOPANIC_API_PLAN', 'developer')
mcp = FastMCP('crypto news')

@mcp.tool()
def get_crypto_news(kind: str='news', num_pages: int=1) -> str:
    news = fetch_crypto_news(kind, num_pages)
    readable = concatenate_news(news)
    return readable

def fetch_crypto_news_page(kind: str='news', page: int=1) -> list:
    try:
        url = f'https://cryptopanic.com/api/{API_PLAN}/v2/posts/'
        params = {'auth_token': API_KEY, 'kind': kind, 'regions': 'en', 'page': page}
        response = requests.get(url, params=params)
        return response.json().get('results', [])
    except Exception:
        return []

def fetch_crypto_news(kind: str='news', num_pages: int=10) -> list:
    all_news = []
    for page in range(1, num_pages + 1):
        news_items = fetch_crypto_news_page(kind, page)
        if not news_items:
            break
        all_news.extend(news_items)
    return all_news

def concatenate_news(news_items: list) -> str:
    concatenated_text = ''
    for idx, news in enumerate(news_items):
        title = news.get('title', 'No Title')
        concatenated_text += f'- {title}\n'
    return concatenated_text.strip()

