            return f"No traffic light definition found for ID '{tls_id}'."
        definition = definitions[0]
        summary = [f'Traffic Light ID: {tls_id}', f'Program ID: {definition.programID}', 'Phases:']
        for i, phase in enumerate(definition.phases):
            summary.append(f"  Phase {i}: duration={phase.duration}s, minDur={phase.minDur}, maxDur={phase.maxDur}, state='{phase.state}'")
        summary.append(f'\nState string length = {len(definition.phases[0].state)} (this is required when setting new light states)')
        return '\n'.join(summary)
    except Exception as e:
        return f"Error while retrieving traffic light phases for '{tls_id}': {e}"

import json
from pathlib import Path
from livekit.agents import function_tool, RunContext
import logging
from livekit.plugins.speechmatics import TurnDetectionMode, SpeakerIdentifier
from livekit.plugins import speechmatics as speechmatics_livekit
from typing import Any
SPEAKERS_FILE = Path(__file__).parent / 'speakers.json'

def save_speakers(raw_speakers: list[Any], label_id: str, name: str) -> None:
    data = []
    for speaker in raw_speakers:
        if isinstance(speaker, dict):
            label, ids = (speaker.get('label', ''), speaker.get('speaker_identifiers', []))
        else:
            label, ids = (speaker.label, speaker.speaker_identifiers)
        if label and ids:
            if label == label_id:
                label = name
            data.append({'label': label, 'speaker_identifiers': ids})
    if data:
        with open(SPEAKERS_FILE, 'w') as f:
            json.dump(data, f, indent=2)

def load_known_speakers() -> list[SpeakerIdentifier]:
    if not SPEAKERS_FILE.exists():
        return []
    with open(SPEAKERS_FILE) as f:
        data = json.load(f)
    return [SpeakerIdentifier(label=entry['label'], speaker_identifiers=entry['speaker_identifiers']) for entry in data if entry.get('label') and entry.get('speaker_identifiers')]
known_speakers = load_known_speakers()
stt = speechmatics_livekit.STT(turn_detection_mode=TurnDetectionMode.SMART_TURN, enable_diarization=True, speaker_active_format='<{speaker_id}>{text}</{speaker_id}>', speaker_passive_format='<PASSIVE><{speaker_id}>{text}</{speaker_id}></PASSIVE>', known_speakers=known_speakers)

