@function_tool(name_override='send_slack_alert')
async def send_slack_security_alert(vulnerability_type: str, severity: str, target_url: str, description: str, evidence: Optional[str]=None, recommendation: Optional[str]=None, thread_ts: Optional[str]=None):
    severity_colors = {'Critical': '#FF0000', 'High': '#FF6600', 'Medium': '#FFB84D', 'Low': '#FFCC00', 'Info': '#0099FF'}
    severity_emojis = {'Critical': '🚨', 'High': '⚠️', 'Medium': '⚡', 'Low': '📝', 'Info': 'ℹ️'}
    color = severity_colors.get(severity, '#808080')
    emoji = severity_emojis.get(severity, '📌')
    blocks = [{'type': 'header', 'text': {'type': 'plain_text', 'text': f'{emoji} {vulnerability_type} Vulnerability Detected', 'emoji': True}}, {'type': 'section', 'fields': [{'type': 'mrkdwn', 'text': f'*Severity:*\n{severity}'}, {'type': 'mrkdwn', 'text': f'*Target:*\n<{target_url}|{target_url}>'}]}, {'type': 'section', 'text': {'type': 'mrkdwn', 'text': f'*Description:*\n{description}'}}]
    if evidence:
        blocks.append({'type': 'section', 'text': {'type': 'mrkdwn', 'text': f'*Evidence/PoC:*\n```{evidence[:500]}```'}})
    if recommendation:
        blocks.append({'type': 'section', 'text': {'type': 'mrkdwn', 'text': f'*Recommendation:*\n{recommendation}'}})
    blocks.append({'type': 'context', 'elements': [{'type': 'mrkdwn', 'text': f"Detected at: {datetime.now(UTC).strftime('%Y-%m-%d %H:%M:%S UTC')}"}]})
    fallback_text = f'{emoji} {severity} {vulnerability_type} vulnerability found at {target_url}'
    if SLACK_WEBHOOK_URL:
        payload = {'channel': SLACK_CHANNEL, 'username': 'Security Scanner Bot', 'icon_emoji': ':shield:', 'text': fallback_text, 'blocks': blocks, 'attachments': [{'color': color, 'fallback': fallback_text}]}
        if thread_ts:
            payload['thread_ts'] = thread_ts
        async with aiohttp.ClientSession() as session:
            async with session.post(SLACK_WEBHOOK_URL, json=payload) as response:
                if response.status == 200:
                    return json_module.dumps({'success': True, 'message': 'Alert sent to Slack successfully'})
                else:
                    error_text = await response.text()
                    return json_module.dumps({'success': False, 'error': f'Failed to send to Slack: {error_text}'})
    else:
        return json_module.dumps({'success': False, 'error': 'No Slack webhook configured. Set SLACK_WEBHOOK_URL in .env file'})

