@function_tool
async def pdf_merge_tool(file1: str, file2: str, output: str) -> str:
    for path in [file1, file2]:
        if not os.path.exists(path):
            return f'Error: File not found: {path}'
    try:
        from PyPDF2 import PdfMerger
    except ImportError:
        try:
            from PyPDF2 import PdfWriter, PdfReader
        except ImportError:
            return 'Error: PyPDF2 is not installed. Install it with: pip install PyPDF2'
        try:
            writer = PdfWriter()
            for pdf_path in [file1, file2]:
                reader = PdfReader(pdf_path)
                for page in reader.pages:
                    writer.add_page(page)
            os.makedirs(os.path.dirname(os.path.abspath(output)), exist_ok=True)
            with open(output, 'wb') as f:
                writer.write(f)
            return f'Successfully merged PDFs:\n  1. {os.path.basename(file1)}\n  2. {os.path.basename(file2)}\n  Output: {output} ({_get_file_size_str(output)})'
        except Exception as e:
            return f'Error merging PDFs: {e}'
    try:
        merger = PdfMerger()
        merger.append(file1)
        merger.append(file2)
        os.makedirs(os.path.dirname(os.path.abspath(output)), exist_ok=True)
        merger.write(output)
        merger.close()
        return f'Successfully merged PDFs:\n  1. {os.path.basename(file1)}\n  2. {os.path.basename(file2)}\n  Output: {output} ({_get_file_size_str(output)})'
    except Exception as e:
        return f'Error merging PDFs: {e}'

