@function_tool
async def pdf_protect_tool(filepath: str, password: str) -> str:
    if not os.path.exists(filepath):
        return f'Error: File not found: {filepath}'
    if not password or len(password) < 1:
        return 'Error: Password cannot be empty.'
    try:
        from PyPDF2 import PdfReader, PdfWriter
    except ImportError:
        return 'Error: PyPDF2 is not installed. Install it with: pip install PyPDF2'
    try:
        reader = PdfReader(filepath)
        writer = PdfWriter()
        for page in reader.pages:
            writer.add_page(page)
        import secrets
        owner_pw = secrets.token_urlsafe(32)
        try:
            writer.encrypt(user_password=password, owner_password=owner_pw, use_128bit=True)
        except TypeError:
            writer.encrypt(password)
        base, ext = os.path.splitext(filepath)
        output_path = f'{base}_protected{ext}'
        with open(output_path, 'wb') as f:
            writer.write(f)
        return f'Successfully password-protected PDF.\n  Source : {os.path.basename(filepath)}\n  Output : {output_path}\n  Size   : {_get_file_size_str(output_path)}\n  Password is set. Do not forget it!'
    except Exception as e:
        return f'Error protecting PDF: {e}'

