import hashlib
from shell_safe_executor import god_tier_tool as function_tool
_ALGORITHMS = {'md5': hashlib.md5, 'sha1': hashlib.sha1, 'sha256': hashlib.sha256, 'sha512': hashlib.sha512, 'sha3_256': hashlib.sha3_256, 'sha3_512': hashlib.sha3_512}

@function_tool
async def hash_string_tool(text: str, algorithm: str) -> str:
    try:
        algo = algorithm.lower().strip()
        if algo not in _ALGORITHMS:
            supported = ', '.join(_ALGORITHMS.keys())
            return f"Unknown algorithm: '{algorithm}'. Supported: {supported}"
        h = _ALGORITHMS[algo]()
        h.update(text.encode('utf-8'))
        digest = h.hexdigest()
        return f'Hash Result:\n  Algorithm: {algo}\n  Input:     {len(text)} chars\n  Digest:    {digest}\n  Length:    {len(digest)} hex chars ({len(digest) * 4} bits)'
    except Exception as e:
        return f'Error hashing string: {e}'

import os
import hashlib
from shell_safe_executor import god_tier_tool as function_tool
_ALGORITHMS = {'md5': hashlib.md5, 'sha1': hashlib.sha1, 'sha256': hashlib.sha256, 'sha512': hashlib.sha512, 'sha3_256': hashlib.sha3_256, 'sha3_512': hashlib.sha3_512}
_CHUNK_SIZE = 8192

def _hash_file(filepath: str, algo_name: str) -> str:
    algo_func = _ALGORITHMS.get(algo_name)
    if not algo_func:
        raise ValueError(f'Unknown algorithm: {algo_name}')
    h = algo_func()
    with open(filepath, 'rb') as f:
        while True:
            chunk = f.read(_CHUNK_SIZE)
            if not chunk:
                break
            h.update(chunk)
    return h.hexdigest()

def _file_size_str(size: int) -> str:
    if size < 1024:
        return f'{size} B'
    elif size < 1024 * 1024:
        return f'{size / 1024:.1f} KB'
    elif size < 1024 * 1024 * 1024:
        return f'{size / (1024 * 1024):.2f} MB'
    else:
        return f'{size / (1024 * 1024 * 1024):.2f} GB'

@function_tool
async def hash_file_tool(filepath: str) -> str:
    try:
        if not os.path.exists(filepath):
            return f'Error: File not found: {filepath}'
        if not os.path.isfile(filepath):
            return f'Error: Not a file: {filepath}'
        file_size = os.path.getsize(filepath)
        sha256_hash = _hash_file(filepath, 'sha256')
        sha512_hash = _hash_file(filepath, 'sha512')
        md5_hash = _hash_file(filepath, 'md5')
        fname = os.path.basename(filepath)
        return f'File Hashes for: {fname}\n  Path:        {filepath}\n  Size:        {_file_size_str(file_size)}\n  SHA256:      {sha256_hash}\n  SHA512:      {sha512_hash}\n  MD5 (legacy, collision-prone — do not trust for integrity): {md5_hash}'
    except PermissionError:
        return f'Error: Permission denied: {filepath}'
    except Exception as e:
        return f'Error hashing file: {e}'

