@function_tool
async def verify_hash_tool(filepath: str, expected_hash: str) -> str:
    try:
        if not os.path.exists(filepath):
            return f'Error: File not found: {filepath}'
        expected = expected_hash.strip().lower()
        hash_len = len(expected)
        algo_by_length = {32: 'md5', 40: 'sha1', 64: 'sha256', 128: 'sha512'}
        algo = algo_by_length.get(hash_len)
        if not algo:
            return f'Error: Cannot detect algorithm from hash length ({hash_len} chars).\nExpected lengths: MD5=32, SHA1=40, SHA256=64, SHA512=128'
        actual_hash = _hash_file(filepath, algo)
        match = actual_hash == expected
        fname = os.path.basename(filepath)
        status = 'MATCH — File integrity verified!' if match else 'MISMATCH — File may be corrupted or modified!'
        symbol = '+' if match else '!'
        return f'[{symbol}] Verification: {status}\n  File:      {fname}\n  Algorithm: {algo.upper()}\n  Expected:  {expected}\n  Actual:    {actual_hash}'
    except Exception as e:
        return f'Error verifying hash: {e}'

import os
import hashlib
from shell_safe_executor import god_tier_tool as function_tool
_ALGORITHMS = {'md5': hashlib.md5, 'sha1': hashlib.sha1, 'sha256': hashlib.sha256, 'sha512': hashlib.sha512, 'sha3_256': hashlib.sha3_256, 'sha3_512': hashlib.sha3_512}
_CHUNK_SIZE = 8192

def _hash_file(filepath: str, algo_name: str) -> str:
    algo_func = _ALGORITHMS.get(algo_name)
    if not algo_func:
        raise ValueError(f'Unknown algorithm: {algo_name}')
    h = algo_func()
    with open(filepath, 'rb') as f:
        while True:
            chunk = f.read(_CHUNK_SIZE)
            if not chunk:
                break
            h.update(chunk)
    return h.hexdigest()

def _file_size_str(size: int) -> str:
    if size < 1024:
        return f'{size} B'
    elif size < 1024 * 1024:
        return f'{size / 1024:.1f} KB'
    elif size < 1024 * 1024 * 1024:
        return f'{size / (1024 * 1024):.2f} MB'
