@function_tool
async def checksum_dir_tool(directory: str) -> str:
    try:
        if not os.path.exists(directory):
            return f'Error: Directory not found: {directory}'
        if not os.path.isdir(directory):
            return f'Error: Not a directory: {directory}'
        results = []
        total_size = 0
        errors = 0
        skipped = 0
        for root, dirs, files in os.walk(directory):
            dirs[:] = [d for d in dirs if not d.startswith('.') and d not in ('node_modules', '__pycache__', '.git', 'venv')]
            for fname in sorted(files):
                fpath = os.path.join(root, fname)
                try:
                    fsize = os.path.getsize(fpath)
                    if fsize > 100 * 1024 * 1024:
                        skipped += 1
                        continue
                    total_size += fsize
                    sha = _hash_file(fpath, 'sha256')
                    rel_path = os.path.relpath(fpath, directory)
                    results.append(f'{sha}  {rel_path}')
                except (PermissionError, OSError):
                    errors += 1
                    continue
        if not results:
            return f'No files found in: {directory}'
        header = f'Checksums for: {directory}\nFiles: {len(results)} | Total size: {_file_size_str(total_size)}'
        if errors:
            header += f' | Errors: {errors}'
        if skipped:
            header += f' | Skipped (>100MB): {skipped}'
        header += f"\n{'=' * 55}"
        if len(results) > 200:
            body = '\n'.join(results[:200])
            body += f'\n... and {len(results) - 200} more files'
        else:
            body = '\n'.join(results)
        return f'{header}\n{body}'
    except Exception as e:
        return f'Error generating checksums: {e}'

import os
import logging
from shell_safe_executor import god_tier_tool as function_tool
logger = logging.getLogger('shell_ocr')

def _ocr_with_pytesseract(image):
    import pytesseract
    text = pytesseract.image_to_string(image)
    return (text.strip(), 'pytesseract')

def _ocr_with_easyocr(image_path: str):
    import easyocr
    reader = easyocr.Reader(['en'], gpu=False)
    results = reader.readtext(image_path, detail=0)
    return ('\n'.join(results).strip(), 'easyocr')

def _do_ocr(image_path: str) -> tuple:
    from PIL import Image
    with Image.open(image_path) as raw:
        img = raw.convert('L') if raw.mode != 'L' else raw.copy()
    try:
        text, engine = _ocr_with_pytesseract(img)
        if text:
            return (text, engine)
    except ImportError:
        logger.debug('pytesseract not installed; trying easyocr')
    except Exception as e:
        try:
            from pytesseract import TesseractNotFoundError
            if isinstance(e, TesseractNotFoundError):
                logger.warning('Tesseract binary not on PATH (install or set TESSERACT_CMD). Falling back to easyocr.')
            else:
                logger.debug('pytesseract failed: %s', e)
        except ImportError:
            logger.debug('pytesseract failed: %s', e)
    try:
        text, engine = _ocr_with_easyocr(image_path)
        if text:
            return (text, engine)
    except ImportError:
        logger.debug('easyocr not installed')
    except Exception as e:
        logger.debug('easyocr failed: %s', e)
    return ('', 'none')

@function_tool
async def ocr_image_tool(image_path: str) -> str:
    try:
        if not os.path.exists(image_path):
            return f'Error: File not found: {image_path}'
        text, engine = _do_ocr(image_path)
        if not text:
            return 'No text detected in the image.'
        char_count = len(text)
        word_count = len(text.split())
        line_count = len(text.splitlines())
        return f"OCR Result (engine: {engine}):\nStats: {word_count} words, {char_count} chars, {line_count} lines\n{'=' * 50}\n{text}"
    except ImportError:
        return 'Error: OCR requires pytesseract or easyocr. Install with: pip install pytesseract Pillow (or pip install easyocr)'
    except Exception as e:
        logger.error(f'OCR failed: {e}')
        return f'Error during OCR: {e}'

